import{_ as t,c as o,o as a,ae as r}from"./chunks/framework.CXzlQjHd.js";const b=JSON.parse('{"title":"Contributing to fAIr","description":"","frontmatter":{},"headers":[],"relativePath":"contributing.md","filePath":"contributing.md"}'),n={name:"contributing.md"};function i(s,e,u,l,c,h){return a(),o("div",null,e[0]||(e[0]=[r('<h1 id="contributing-to-fair" tabindex="-1">Contributing to fAIr <a class="header-anchor" href="#contributing-to-fair" aria-label="Permalink to &quot;Contributing to fAIr&quot;">​</a></h1><h2 id="welcome" tabindex="-1">🤗 Welcome <a class="header-anchor" href="#welcome" aria-label="Permalink to &quot;:hugs: Welcome&quot;">​</a></h2><p>👍🎉 First off, I&#39;m really glad you&#39;re reading this, because we need volunteer developers to help with the development of fAIr! 🎉👍</p><p>We welcome and encourage contributors of all skill levels and we are committed to making sure your participation in our tech collective is inclusive, enjoyable and rewarding. If you have never contributed to an open-source project before, we are a good place to start and will make sure you are supported every step of the way. If you have <strong>any</strong> questions, please ask!</p><p>There are many ways to contribute to this repository:</p><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h2><p>Adding test cases, or simply testing out existing functionality.</p><h2 id="report-bugs-and-suggest-improvements" tabindex="-1">Report bugs and suggest improvements <a class="header-anchor" href="#report-bugs-and-suggest-improvements" aria-label="Permalink to &quot;Report bugs and suggest improvements&quot;">​</a></h2><p>The <a href="https://github.com/hotosm/fAIr/issues" target="_blank" rel="noreferrer">issue queue</a> is the best way to get started. There are issue templates for BUGs and FEATURES that you can use, or you can create your own. Once you have submitted an issue, it will be assigned a label out of these <a href="https://github.com/hotosm/fAIr/labels" target="_blank" rel="noreferrer">label categories</a>. If you are wondering where to start, you can filter by the GoodFirstIssue label.</p><h2 id="code-contributions" tabindex="-1">Code contributions <a class="header-anchor" href="#code-contributions" aria-label="Permalink to &quot;Code contributions&quot;">​</a></h2><p>Fork this repository, Maintain your local changes on a separate branch and Create pull requests (PRs) for changes that you think are needed. We would really appreciate your help!</p><h2 id="documentation-contributions" tabindex="-1">Documentation contributions <a class="header-anchor" href="#documentation-contributions" aria-label="Permalink to &quot;Documentation contributions&quot;">​</a></h2><p>Create pull requests (PRs) for changes that you think are needed to the documentation of fAIr. As of now you can find the documentation work at the docs directory.</p><h2 id="thank-you" tabindex="-1">🤝 Thank you <a class="header-anchor" href="#thank-you" aria-label="Permalink to &quot;:handshake: Thank you&quot;">​</a></h2><p>Thank you very much in advance for your contributions!! Please ensure you refer to our <a href="https://github.com/hotosm/fAIr/blob/master/docs/Code-of-Conduct.md" target="_blank" rel="noreferrer">Code of Conduct</a>. If you&#39;ve read the guidelines, but you are still not sure how to contribute on Github, please reach out to us via our Slack #geospatial-tech-and-innovation.</p>',15)]))}const p=t(n,[["render",i]]);export{b as __pageData,p as default};
